"""Write project-authored source summaries and prior-result pointers.

Raw source text, imagery, accession tables and full inscriptions remain on D:.
"""
from pathlib import Path
import hashlib
import json

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[3]
RAW = Path("D:/projects/indus_valley_script/data/raw/2026-10-24-urban-form-and-inscription-ecology/inscriptions")


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


sources = []


def source(sid, authors, year, title, url, path, locators, exposure, lineage):
    p = ROOT / path
    sources.append(dict(source_id=sid, authors=authors, year=year, title=title, url=url, logical_path=path, physical_path=str(p.resolve()), bytes=p.stat().st_size, sha256=digest(p), exact_locators=locators, access="held source reused; public URL checked or inherited from manifest", rights_status="rights-unverified", handling="local-only primary source and derivatives", exposure=exposure, source_lineage=lineage))


