observations = []


def obs(town, phase, feature, assertion, sid, locator, status="source-qualified", dating="No direct manufacture or construction sample joined.", uncertainty="", missing=None, **extra):
    field_missing_reasons = {}
    if phase is None:
        field_missing_reasons["phase"] = "No independently qualified phase for this named object or relation in the inspected passage; a neighbouring building's phase is not transferred."
    if "material" in extra and extra["material"] is None:
        field_missing_reasons["material"] = "No material observation entered from this selected context row."
    observations.append(dict(id=f"INS-{len(observations)+1:03d}", town=town, phase=phase, feature=feature, assertion=assertion, source_id=sid, locator=locator, evidence_status=status, dating_basis=dating, uncertainty=uncertainty or "Report-level assertion; no new object measurement in this study.", missing_reason=missing, field_missing_reasons=field_missing_reasons, **extra))


