prior = []


def result(pid, path, fields, relevance, status):
    p = ROOT / path
    data = json.loads(p.read_text(encoding="utf-8"))
    selected = {}
    for pointer in fields:
        value = data
        for segment in pointer.strip("/").split("/"):
            value = value[int(segment)] if isinstance(value, list) else value[segment]
        selected[pointer] = value
    prior.append(dict(id=pid, exact_output=path, sha256=digest(p), values=selected, relevance_to_urban_study=relevance, evidential_status=status, fresh_confirmation_here=False))


